// Spends nothing unless TrendsFast holds your saved brand and the free quote fits Max Credits.
const context = $('Get brand context (free)').first().json.context;
const quote = $input.first().json;
const maxCredits = 10; // keep equal to Max Credits on 'Find customer conversations (10 credits)'
if (!context || context.kind !== 'CONFIRMED_CONTEXT' || !context.context_id) {
  throw new Error('No saved brand context yet. Set up your brand in the TrendsFast dashboard first. Nothing was spent.');
}
if (quote.version !== 'trends-credit-quote-v3' || quote.available !== true || !Number.isInteger(quote.credits)) {
  throw new Error('The quote is not available right now. Nothing was spent.');
}
if (quote.credits > maxCredits) {
  throw new Error(`Customers costs ${quote.credits} credits now, above this workflow's Max Credits of ${maxCredits}. Nothing was spent.`);
}
return [{ json: { context_id: context.context_id } }];

// Turns the Customers result into a short digest: where people talked and what they asked.
const result = $input.first().json;
const items = Array.isArray(result.data?.items) ? result.data.items : [];
const where = (item) => {
  const community = item.current_observation?.conversation?.community;
  const platform = item.entity?.platform ?? 'Unknown platform';
  return community ? `${platform} ${community}` : platform;
};
const venues = {};
for (const item of items) venues[where(item)] = (venues[where(item)] ?? 0) + 1;
const venueLines = Object.entries(venues)
  .sort((a, b) => b[1] - a[1])
  .map(([venue, count]) => `- ${venue}: ${count}`);
const conversationLines = items.slice(0, 10).map((item, index) => {
  const observation = item.current_observation ?? {};
  const conversation = observation.conversation ?? {};
  return [
    `${index + 1}. ${observation.title ?? 'Untitled conversation'}`,
    `   Where: ${where(item)}`,
    conversation.question?.value ? `   Asked: ${conversation.question.value}` : null,
    conversation.problem?.value ? `   Problem: ${conversation.problem.value}` : null,
    `   Link: ${item.entity?.original_url ?? 'no link'}`,
    `   Seen: ${observation.observed_at ?? 'unknown'}`,
  ].filter(Boolean).join('\n');
});
const week = String(result.generated_at ?? '').slice(0, 10);
const text = [
  `Where your customers talked (week of ${week})`,
  venueLines.length
    ? `Venues:\n${venueLines.join('\n')}`
    : 'No conversations matched this week. An empty result costs 0 credits.',
  ...conversationLines,
  `Result ${result.result_id}, request ${result.request_id}, ${result.usage?.this_request_credits ?? 0} credits.`,
  ...(result.data?.limitations ?? []).map((note) => `Note: ${note}`),
].join('\n\n');
return [{
  json: {
    subject: `Where your customers talked, week of ${week}`,
    text,
    result_id: result.result_id,
    request_id: result.request_id,
  },
}];
